  const dots = Array.from({ length: 14 }, (_, i) => { const k = new Date(Date.now() - (13 - i) * 864e5).toISOString().slice(0, 10), c = Object.keys(dGet(k)).length; return `<i class="dd ${c >= 3 ? "full" : c ? "some" : ""} ${k === key ? "today" : ""}" title="${k}: ${c} of 3"></i>`; }).join("");
