  const line = (L) => L.map((x) => `${X(x[0]).toFixed(1)},${Y(x[1]).toFixed(1)}`).join(" "), years = [...new Set(months.map((m) => m.slice(0, 4)))], step = Math.ceil(years.length / 7);
