  const who = (k) => { const id = g.h[k + "FideId"], p = id ? cpP(id) : null; return `<div class="lvp">${p ? cpFace(p) : ""}<b>${esc(p ? cpName(p) : (g.h[k] || k))}</b>${g.h[k + "Elo"] ? `<small class="fine">${g.h[k + "Elo"]}</small>` : ""}<span class="lvclk num">${esc(clkOf(k))}</span></div>`; };
